#include <atomic>
#include <thread>
#include <vector>
#include <new>   // std::hardware_destructive_interference_size

constexpr int T = 4;
constexpr long ITERS = 50'000'000;

// BAD: 4 counters share one or two cache lines -> ping-pong on every ++
struct Bad { std::atomic<long> c[T]; };

// GOOD: each counter sits alone on its own cache line
struct alignas(64) Padded { std::atomic<long> c{0}; };
struct Good { Padded c[T]; };

template <class F>
void run(F&& bump) {
    std::vector<std::thread> th;
    for (int i = 0; i < T; ++i) th.emplace_back(bump, i);
    for (auto& t : th) t.join();
}

int main() {
    Bad bad;  for (auto& a : bad.c) a = 0;
    run([&](int i){ for (long k=0;k<ITERS;++k) bad.c[i].fetch_add(1, std::memory_order_relaxed); });

    Good good;
    run([&](int i){ for (long k=0;k<ITERS;++k) good.c[i].c.fetch_add(1, std::memory_order_relaxed); });
    // 'good' typically finishes several times faster: no inter-core invalidation.
}

#include <atomic>
#include <cstddef>

// In an SPSC queue, producer writes `tail`, consumer writes `head`.
// Keep them on different cache lines so they don't invalidate each other.
struct Indices {
    alignas(64) std::atomic<size_t> head{0};   // owned by consumer
    alignas(64) std::atomic<size_t> tail{0};   // owned by producer
};
// Without alignas, head & tail share a line and every push invalidates the
// consumer's cached index (and every pop invalidates the producer's) -> ping-pong.

